def hsv_rgb(h, s, v):
    """HSV (0..1) to RGB (0..1), the standard formula."""
    i, f = int(h * 6) % 6, h * 6 - int(h * 6)
    p, q, t = v * (1 - s), v * (1 - s * f), v * (1 - s * (1 - f))
    return [(v, t, p), (q, v, p), (p, v, t), (p, q, v), (t, p, v), (v, p, q)][i]


def band_colors():
    """One colour per band, following the visible spectrum: the lowest band is red (the lowest frequency of light), each
    octave up moves the hue by the same step, and the highest band is violet. Softened, with yellow-greens toned down
    because they look brighter than the other hues."""
    out = []
    for i in range(10):
        hue = 6 + i * (272 - 6) / 9
        r, g, b = hsv_rgb(hue / 360, 0.62, 0.9 - 0.12 * math.exp(-((hue - 95) / 45) ** 2))
        out.append('#%02x%02x%02x' % (round(r * 255), round(g * 255), round(b * 255)))
    return out


