def low_boost(f, frac=0.3, cap=8.0):
    """Linear gain that makes up part of the ear's loss at low frequencies (A-weighting), so low thumps and tones are not lost under hiss."""
    f2 = float(f) ** 2
    ra = 12194.0 ** 2 * f2 * f2 / ((f2 + 20.6 ** 2) * math.sqrt((f2 + 107.7 ** 2) * (f2 + 737.9 ** 2)) * (f2 + 12194.0 ** 2))
    a = 20 * math.log10(max(ra, 1e-12)) + 2.0
    return 10 ** (min(cap, max(0.0, -frac * a)) / 20)


