def preset_color(name):
    if name == 'White' and THEME_NAME == 'light':
        return '#8c99ae'
    return PRESET_COLORS[name]


def name_color(name):
    """Stable pseudo-random colour for user presets."""
    h = (zlib.crc32(name.encode('utf-8')) % 360) / 60.0
    v, sat = 0.88, 0.55
    c = v * sat
    x = c * (1 - abs(h % 2 - 1))
    r, g, b = [(c, x, 0), (x, c, 0), (0, c, x), (0, x, c), (x, 0, c), (c, 0, x)][int(h) % 6]
    m = v - c
    return tuple(int((u + m) * 255) for u in (r, g, b))


def dbv(db):
    return [OFF if d <= MIN else d for d in db]


