def clampf(v, lo, hi, default):
    """`v` as a number within lo..hi, or `default` when it is not a finite number."""
    try:
        f = float(v)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(f):
        return default
    f = min(hi, max(lo, f))
    return int(round(f)) if isinstance(lo, int) else f


def sane(kind, d, base):
    """A copy of `base` updated with the valid entries of `d`: a damaged or hand-edited config file can never push a
    setting outside the range of its control, give it the wrong type, or add unknown keys."""
    out = dict(base)
    if not isinstance(d, dict):
        return out
    for k, v in d.items():
        if k in FLAGS and k in out:
            out[k] = bool(v)
        elif k in RANGES.get(kind, {}):
            lo, hi = RANGES[kind][k]
            out[k] = clampf(v, lo, hi, out.get(k, lo))
        elif k in CHOICES.get(kind, {}) and v in CHOICES[kind][k]:
            out[k] = v
    return out


def sane_db(v):
    """Ten band levels within MIN..0 dB, or None."""
    try:
        db = [clampf(x, MIN, 0.0, MIN) for x in v]
    except TypeError:
        return None
    return db if len(db) == 10 else None


def boxcar(x, k, mode='valid'):
    """Moving average, the same as np.convolve(x, np.ones(k) / k, mode) but computed with running sums in linear time
    (a direct convolution grows with the square of the sample rate and stalled the audio at 192 kHz)."""
    if mode == 'same':
        out = boxcar(np.concatenate((np.zeros(k - 1), x, np.zeros(k - 1))), k)
        return out[(k - 1) // 2:(k - 1) // 2 + max(len(x), k)]
    c = np.cumsum(np.concatenate(([0.0], x)))
    return (c[k:] - c[:-k]) / k


# Every duration (sleep timer, chimes, animations, autosave) is measured with time.monotonic(): Windows' own uptime
# clock, which a change of the system time cannot move and which keeps running while the computer sleeps.


def data_dir():
    base = os.environ.get('LOCALAPPDATA')
    d = Path(base) / 'EarBear' if base else Path.home() / '.earbear'
    d.mkdir(parents=True, exist_ok=True)
    return d


class Log:
    """Small append-only file logger with a size cap."""

    def __init__(self):
        self.path = data_dir() / 'earbear.log'
        self.debug = False
        self.lock = threading.Lock()
        try:
            if self.path.exists() and self.path.stat().st_size > 512 * 1024:
                self.path.write_bytes(self.path.read_bytes()[-128 * 1024:])
        except OSError:
            pass

    def write(self, level, msg):
        try:
            with self.lock:
                if self.path.exists() and self.path.stat().st_size > 1024 * 1024:     # never grows past 1 MB, even at run time
                    self.path.write_bytes(self.path.read_bytes()[-128 * 1024:])
                with open(self.path, 'a', encoding='utf-8') as f:
                    f.write('%s %-5s %s\n' % (time.strftime('%Y-%m-%d %H:%M:%S'), level, msg))
        except OSError:
            pass

    def info(self, msg):
        self.write('INFO', msg)

    def dbg(self, msg):
        if self.debug:
            self.write('DEBUG', msg)

    def exc(self, ctx):
        self.write('ERROR', ctx + '\n' + traceback.format_exc())


LOG = Log()


# ---------- single instance (Windows) ----------
def acquire_single_instance():
    """Return False if another instance owns the mutex (after asking it to show itself)."""
    if sys.platform != 'win32':
        return True
    try:
        import ctypes
        k = ctypes.windll.kernel32
        k.CreateMutexW.restype = ctypes.c_void_p
        k.OpenEventW.restype = ctypes.c_void_p
        if os.environ.get('EARBEAR_LAUNCHER') == '1':   # the launcher already created the mutex
            return True
        k.CreateMutexW(None, False, MUTEX_NAME)
        if ctypes.get_last_error() == 183 or k.GetLastError() == 183:   # ERROR_ALREADY_EXISTS
            ev = k.OpenEventW(0x0002, False, EVENT_NAME)
            if ev:
                ctypes.windll.user32.AllowSetForegroundWindow(-1)
                k.SetEvent(ctypes.c_void_p(ev))
            return False
    except Exception:
        LOG.exc('single instance check')
    return True


# ---------- engine ----------
class Engine:
    """Spectral noise synthesis (random-phase spectra, overlap-add) with binaural, swell and rhythm layers."""

    def __init__(self, fs):
        self.rng = np.random.default_rng()
        self.tail = np.zeros((H, 2))
        self.cur = np.full(10, OFF)
        self.target = np.full(10, OFF)
        self.tape, self.width, self.vol, self.trim = 0.0, 1.0, 0.0, 1.0
        self.playing, self.run, self.fade_on = False, True, True
        self.safe_until = 0.0
        self.mcur = 0.0
        self.slew_until = 0.0
        self.fifo, self.chunk, self.pos = deque(), None, 0
        self.bin, self.sw, self.rh = dict(DEF_BIN), dict(DEF_SW), dict(DEF_RH)
        self.bcur = self.swd = 0.0
        self.cue_req, self.cue_pos, self.cue_wait, self.cue_kind = False, None, 0, 'Bell'
        self.dcur, self.duck_media = 1.0, False
        self.safe_g, self.err_t = 1.0, -1e9
        self.wind = 1.0                             # sleep wind-down: 1 = full level, 0 = silent
        self.phl = self.phr = self.swph = 0.0
        self.swj = 1.0
        self.lock = threading.Lock()                # setup (device change) never runs in the middle of a block
        self.setup(fs)

    def setup(self, fs):
        """Recompute everything that depends on the sample rate (also called on output device change)."""
        with self.lock:
            self._setup(fs)

    def _setup(self, fs):
        self.fs = fs
        self.depth = max(6, math.ceil(0.25 * fs / H))            # a quarter of a second queued at any sample rate
        f = np.maximum(np.arange(N // 2 + 1) * fs / N, 1.0)
        self.lf = np.log2(f)
        self.shape = np.clip(f / 20, 0, 1) ** 2 / np.sqrt(1 + (f / 19000) ** 8)   # no subsonics, soft cut above 19 kHz
        self.win = np.sin(np.pi * (np.arange(N) + 0.5) / N)
        self.ref = self.power(dbv(PRESETS['Pink']))
        self.norm = N / (2 * math.sqrt(self.ref))
        self.maxn = int(fs * 0.6)
        self.rbuf = np.zeros((H + self.maxn, 2))
        self.events, self.rk, self.rpos, self._rkey, self._wkey, self.waves = [], 0, 0, None, None, None
        self.cue_wave = self._build_cue()

    def _build_cue(self):
        """Chime for the selected kind, peak 0.7 relative to the noise level, trimmed to its audible length."""
        fs = self.fs
        n = int(fs * 4.2)
        w = np.zeros(n)

        def note(f, t0, dec, parts, att=0.01):
            i0 = int(t0 * fs)
            t = np.arange(n - i0) / fs
            tone = sum(a * np.sin(2 * math.pi * f * r * t) * np.exp(-t / (dec * dm)) for r, a, dm in parts)
            w[i0:] += (1 - np.exp(-t / att)) * np.exp(-t / dec) * tone
        kind = self.cue_kind
        if kind == 'Glass':
            for k, f in enumerate((784.0, 1046.5, 1318.5)):
                note(f, k * 0.2, 0.9, ((1, 1, 1), (2.76, 0.25, 0.3), (5.4, 0.08, 0.15)))
        elif kind == 'Marimba':
            for k, f in enumerate((392.0, 493.9, 587.3, 784.0)):
                note(f, k * 0.17, 0.28, ((1, 1, 1), (4, 0.35, 0.25), (10, 0.1, 0.1)), 0.003)
        elif kind == 'Bowl':
            note(432.0, 0.0, 1.5, ((1, 1, 1), (2.71, 0.3, 0.4), (5.1, 0.1, 0.2)), 0.04)
            note(435.6, 0.0, 1.5, ((1, 0.8, 1),), 0.04)                 # slight detune: slow beating
        else:
            for f, t0 in ((392.0, 0.0), (523.25, 0.34)):
                note(f, t0, 0.7, ((1, 1, 1), (2, 0.3, 0.43), (3, 0.1, 0.21)), 0.02)
        w = w / max(float(np.abs(w).max()), 1e-9) * 0.7
        return w[:int(np.nonzero(np.abs(w) > 0.002)[0][-1]) + 1]

    def amp(self, db, tape=0.0):
        return 10 ** (np.interp(self.lf - tape, LF, db) / 20) * self.shape

    def power(self, db, tape=0.0):
        g = self.amp(db, tape)
        return float((g * g).sum())

    def hop(self, cur, tape, width):
        g = self.amp(cur, tape)
        n, w = len(g), width
        k = 1 / math.sqrt(1 + w * w)

        def sig():
            X = g * (self.rng.standard_normal(n) + 1j * self.rng.standard_normal(n))
            X[0] = 0
            return np.fft.irfft(X, N) * self.win
        m = sig()
        s = sig() if w > 0 else 0
        y = np.stack([k * (m + w * s), k * (m - w * s)], axis=1)
        out = y[:H] + self.tail
        self.tail = y[H:]
        out *= self.norm
        self._swell(out)
        self._binaural(out)
        self._rhythm(out)
        return out

    # --- layers ---
    def _swell(self, out):
        sw = self.sw
        tgt = float(sw['depth']) if sw['on'] else 0.0
        self.swd += (tgt - self.swd) * 0.2
        if self.swd < 1e-3 and not sw['on']:
            return
        w = 2 * math.pi / (max(2.0, float(sw['period'])) * self.swj * self.fs)
        ph = self.swph + w * np.arange(H)
        env = (0.5 - 0.5 * np.cos(ph)) ** 1.4          # slow rise, sharper crest
        out *= ((1 - self.swd) + self.swd * env)[:, None]
        self.swph += w * H
        if self.swph >= 2 * math.pi:                    # new cycle: vary the period a little
            self.swph -= 2 * math.pi
            self.swj = float(self.rng.uniform(0.8, 1.25))

    def _binaural(self, out):
        b = self.bin
        tgt = 10 ** (float(b['level']) / 20) if b['on'] else 0.0
        a0 = self.bcur
        self.bcur = a0 + (tgt - a0) * 0.25
        if self.bcur < 1e-5 and a0 < 1e-5:
            return
        ramp = np.linspace(a0, self.bcur, H, endpoint=False)
        t = np.arange(H) / self.fs
        fl, fr = b['carrier'] - b['beat'] / 2, b['carrier'] + b['beat'] / 2
        ramp = ramp * (2.0 * low_boost(b['carrier']) / max(self.trim, 0.05))     # relative to the noise as heard, not to its pre-trim level
        out[:, 0] += ramp * np.sin(self.phl + 2 * math.pi * fl * t)
        out[:, 1] += ramp * np.sin(self.phr + 2 * math.pi * fr * t)
        self.phl = (self.phl + 2 * math.pi * fl * H / self.fs) % (2 * math.pi)
        self.phr = (self.phr + 2 * math.pi * fr * H / self.fs) % (2 * math.pi)

    def chiming(self):
        return self.cue_wait > 0 or self.cue_pos is not None

    def _cue_block(self):
        """Next block of the chime (starts two hops after the request so the noise has time to duck), or None."""
        if self.cue_req:
            self.cue_req, self.cue_wait, self.cue_pos = False, 2, None
        if self.cue_wait > 0:
            self.cue_wait -= 1
            if self.cue_wait == 0:
                self.cue_pos = 0
            return None
        if self.cue_pos is None:
            return None
        seg = self.cue_wave[self.cue_pos:self.cue_pos + H]
        block = np.zeros((H, 2))
        block[:len(seg)] = seg[:, None]
        self.cue_pos += H
        if self.cue_pos >= len(self.cue_wave):
            self.cue_pos = None
        return block

    def _waves(self):
        r = self.rh
        key = (r['tone'], r['decay'], self.fs)
        if key != self._wkey:
            self._wkey = key
            ws = []
            for k in (1.0, 0.72, 1.4, 2.0):             # small variants, used by random drops
                f, d = r['tone'] * k, max(0.002, r['decay'] / 1000.0 / math.sqrt(k))
                n = int(min(self.maxn, self.fs * d * 6))
                t = np.arange(n) / self.fs
                env = np.exp(-t / d) * (1 - np.exp(-t / 0.0015))
                body = np.sin(2 * math.pi * f * t * (1 + 0.3 * np.exp(-t / (d * 0.5))))
                ker = max(1, int(self.fs / (f * 2.5)))
                nz = boxcar(self.rng.standard_normal(n + ker - 1), ker)
                nz /= max(float(np.abs(nz).max()), 1e-9)
                w = env * (0.7 * body + 0.3 * nz)
                ws.append(w / max(float(np.abs(w).max()), 1e-9))
            self.waves = ws
            cl = []                                     # wheel thumps: deep, dry, with a short low knock; one glides up, the other down
            for glide, dm in ((-0.3, 1.0), (0.45, 0.95)):
                f, d = r['tone'], max(0.01, r['decay'] / 1000.0 * dm)
                n = int(min(self.maxn, self.fs * d * 7))
                t = np.arange(n) / self.fs
                ph = 2 * math.pi * np.cumsum(f * (1 + glide * np.exp(-t / 0.018))) / self.fs
                body = (np.sin(ph) + 0.6 * np.sin(2 * ph) + 0.35 * np.sin(3 * ph)) * np.exp(-t / d)    # harmonics keep it audible on small speakers
                ker = max(1, min(int(self.fs / 300), n // 2))
                nz = boxcar(self.rng.standard_normal(n + ker - 1), ker)
                knock = nz / max(float(np.abs(nz).max()), 1e-9) * np.exp(-t / 0.012)
                k2 = max(1, min(int(self.fs / 1000), n // 2))                # a faint rail rattle on top of the thump
                rz = boxcar(self.rng.standard_normal(n + k2 - 1), k2)
                rattle = rz / max(float(np.abs(rz).max()), 1e-9) * np.exp(-t / 0.045)
                w = (1 - np.exp(-t / 0.0015)) * (body / 1.95 + 0.6 * knock + 0.12 * rattle)
                cl.append(w / max(float(np.abs(w).max()), 1e-9))
            self.thumps = cl
            cw = []                                     # crackle: very short, noisy ticks of different pitch and length
            for k, dm in ((0.6, 1.0), (0.8, 0.6), (1.0, 0.8), (1.3, 0.5), (1.7, 0.4), (2.3, 0.3)):
                d = max(0.0012, r['decay'] / 1000.0 * dm)
                n = int(min(self.fs * 0.09, self.fs * d * 6))
                t = np.arange(n) / self.fs
                ker = max(1, int(self.fs / (r['tone'] * k * 2.5)))
                nz = boxcar(self.rng.standard_normal(n + ker - 1), ker)
                lk = min(ker * 8, n)                                              # kernel never longer than the tick
                nz -= boxcar(nz, lk, 'same')[:n]               # drop the slow part: a tick, not a thud
                w = np.exp(-t / d) * (1 - np.exp(-t / 0.0004)) * nz
                cw.append(w / max(float(np.abs(w).max()), 1e-9))
            self.cwaves = cw
        return self.waves

    def _add(self, i, w, amp, pan):
        n = len(w)
        self.rbuf[i:i + n, 0] += w * (amp * (1 - max(0.0, pan)))
        self.rbuf[i:i + n, 1] += w * (amp * (1 + min(0.0, pan)))

    def _rhythm(self, out):
        r = self.rh
        if r['on']:
            waves = self._waves()
            gain = 10 ** (float(r['level']) / 20) * 2.4 * low_boost(r['tone']) / max(self.trim, 0.05)
            if r['pattern'] == 'Crackle':
                for _ in range(self.rng.poisson(max(0.0, float(r['drops'])) * H / self.fs)):
                    pos = int(self.rng.integers(0, H))
                    amp = float(self.rng.random() ** 2.2 * 0.9 + 0.08)         # mostly soft, a few loud pops
                    pan = float(self.rng.uniform(-0.7, 0.7))
                    for _ in range(1 + (int(self.rng.integers(1, 4)) if self.rng.random() < 0.2 else 0)):
                        self._add(pos, self.cwaves[int(self.rng.integers(0, len(self.cwaves)))], amp * gain, pan)
                        pos += int(self.rng.integers(int(self.fs * 0.004), int(self.fs * 0.04)))
                        amp *= 0.7
            elif r['pattern'] == 'Drops':
                for _ in range(self.rng.poisson(max(0.0, float(r['drops'])) * H / self.fs)):
                    self._add(int(self.rng.integers(0, H)), waves[int(self.rng.integers(0, 4))],
                              float(self.rng.uniform(0.25, 1.0)) * gain, float(self.rng.uniform(-0.6, 0.6)))
            else:
                cyc = self.fs * 60.0 / max(5.0, float(r['bpm']))
                key = (round(cyc), r['pattern'])
                if key != self._rkey:
                    self._rkey, self.events, self.rk = key, [], int(self.rpos // cyc) + 1
                pat = PATTERNS[r['pattern']]
                while self.rk * cyc < self.rpos + H:
                    self.events += [(int((self.rk + off) * cyc), a, p) for off, a, p in pat]
                    self.rk += 1
                keep = []
                for ht, a, p in self.events:
                    if ht < self.rpos:
                        continue
                    if ht < self.rpos + H:
                        self._add(ht - self.rpos, self.thumps[0 if a >= 0.95 else 1] if r['pattern'] == 'Train' else waves[0], a * gain, p)
                    else:
                        keep.append((ht, a, p))
                self.events = keep
        else:
            self.events, self._rkey = [], None
        self.rpos += H
        out += self.rbuf[:H]
        self.rbuf[:-H] = self.rbuf[H:].copy()
        self.rbuf[-H:] = 0

    # --- streaming ---
    def safe(self, h, level):
        """Last stage before the output: mutes a broken block and caps loudness at SAFE_RMS times `level`.

        Presets and scenes stay below 1.7x, so the cap only acts on extreme layer settings or a computation gone wrong.
        A sudden jump is cut at once; recovery takes about a second, gliding inside each block to avoid clicks."""
        if not np.isfinite(h).all():
            h = np.zeros_like(h)
        r = math.sqrt(float(np.mean(h * h)))
        g = min(1.0, SAFE_RMS * level / r) if r > 0 else 1.0
        g = min(g, self.safe_g + 0.05)
        g0 = g if g < 0.5 * self.safe_g else self.safe_g
        self.safe_g = g
        if g0 == g == 1.0:
            return h
        return h * np.linspace(g0, g, len(h), endpoint=False)[:, None]

    def produce(self):
        """Producer thread: keeps ~0.25 s of audio buffered so the audio callback does no computation."""
        while self.run:
            try:
                if len(self.fifo) >= self.depth:
                    time.sleep(0.02)                                    # a block lasts 43 ms and six are queued: half the wake-ups
                    continue
                mt = RMS_MAX * self.vol ** 2 * self.trim * self.wind if self.playing else 0.0
                if mt == 0 and self.mcur < 1e-5:
                    self.mcur = 0.0
                    self.cur[:] = self.target
                    self.fifo.clear()
                    time.sleep(0.08)                                    # silent and paused: wake rarely
                    continue
                self.cur += (self.target - self.cur) * (0.08 if time.monotonic() < self.slew_until else 0.35)   # a new preset glides in instead of jumping
                if self.playing:   # rises are always gradual; falls are softer than rises are slow
                    slow = self.fade_on or time.monotonic() < self.safe_until
                    a = (0.05 if slow else 0.15) if mt > self.mcur else 0.12
                    if self.vol > WARN and mt > self.mcur:
                        a = 0.0164                                      # above the protection threshold every rise takes about 6 s
                else:              # paused: fade out
                    a = 0.06 if self.fade_on else 0.3
                mn = self.mcur + (mt - self.mcur) * a
                chime = self.chiming()
                dt = 0.5 if (chime or self.duck_media) else 1.0         # other sound or a chime: half the volume
                dn = self.dcur + (dt - self.dcur) * ((0.5 if chime else 0.15) if dt < self.dcur else 0.1)
                ramp = np.linspace(self.mcur, mn, H, endpoint=False)[:, None]
                with self.lock:
                    h = self.hop(self.cur, self.tape, self.width)
                h = h * ramp * np.linspace(self.dcur, dn, H, endpoint=False)[:, None]
                cue = self._cue_block()
                if cue is not None:
                    h = h + cue * ramp                                  # the chime itself is not ducked
                h = self.safe(h, max(self.mcur, mn) / max(self.trim, 0.05))     # the level the noise itself has after trimming
                self.mcur, self.dcur = mn, dn
                self.fifo.append(np.tanh(h).astype(np.float32))
            except Exception:
                if time.monotonic() - self.err_t > 60:                       # a persistent error is logged once a minute, not 10 times a second
                    self.err_t = time.monotonic()
                    LOG.exc('engine producer')
                self.fifo.clear()                                       # and nothing half-computed is played
                time.sleep(0.1)

    def callback(self, out, frames, t, status):
        i = 0
        while i < frames:
            if self.chunk is None or self.pos >= len(self.chunk):
                try:
                    self.chunk, self.pos = self.fifo.popleft(), 0
                except IndexError:
                    out[i:] = 0
                    return
            take = min(frames - i, len(self.chunk) - self.pos)
            out[i:i + take] = self.chunk[self.pos:self.pos + take]
            self.pos += take
            i += take


# ---------- anti-aliased sprites ----------
def hexrgb(h):
    return tuple(int(h[i:i + 2], 16) for i in (1, 3, 5))


def mix(a, b, t):
    """Blend two '#rrggbb' colours; t=0 gives a, t=1 gives b. Returns an rgb tuple."""
    return tuple(int(x + (y - x) * t) for x, y in zip(hexrgb(a), hexrgb(b)))


def hexs(c):
    return '#%02x%02x%02x' % tuple(c)


def lighter(h, k=0.5):
    return tuple(int(v + (255 - v) * k) for v in hexrgb(h))


def png_b64(a):
    h, w = a.shape[:2]
    raw = b''.join(b'\x00' + a[y].tobytes() for y in range(h))

    def ch(t, d):
        return struct.pack('>I', len(d)) + t + d + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
    png = (b'\x89PNG\r\n\x1a\n' + ch(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0))
           + ch(b'IDAT', zlib.compress(raw, 6)) + ch(b'IEND', b''))
    return base64.b64encode(png).decode()


def pill_arr(L, T, col):
    yy, xx = np.mgrid[0:L, 0:T]
    dx = np.abs(xx - (T - 1) / 2)
    dy = np.maximum(0, np.abs(yy - (L - 1) / 2) - ((L - 1) / 2 - (T - 1) / 2))
    cov = np.clip(T / 2 - np.hypot(dx, dy) + 0.5, 0, 1)
    a = np.zeros((L, T, 4), np.uint8)
    a[..., :3] = col
    a[..., 3] = (cov * 255).astype(np.uint8)
    return a


def trash_arr(d, col):
    k = 4
    n = d * k
    yy, xx = (np.mgrid[0:n, 0:n] + 0.5) / n * 16
    m = (yy >= 3.2) & (yy <= 4.6) & (xx >= 2.2) & (xx <= 13.8)
    m |= (yy >= 1.8) & (yy <= 3.2) & (xx >= 5.8) & (xx <= 10.2)
    body = (yy >= 5.4) & (yy <= 14.6) & (xx >= 3.4 + 0.05 * (yy - 5.4)) & (xx <= 12.6 - 0.05 * (yy - 5.4))
    slots = ((np.abs(xx - 6.3) < 0.55) | (np.abs(xx - 9.7) < 0.55)) & (yy >= 7.2) & (yy <= 12.8)
    m |= body & ~slots
    cov = m.reshape(d, k, d, k).mean((1, 3))
    a = np.zeros((d, d, 4), np.uint8)
    a[..., :3] = col
    a[..., 3] = (cov * 255).astype(np.uint8)
    return a


def squircle_sdf(w, h, r):
    """Signed distance (px) to a squircle-cornered rectangle (L4-norm corners); negative inside."""
    r = min(r, w / 2, h / 2)
    yy, xx = np.mgrid[0:h, 0:w] + 0.5
    dx = np.abs(xx - w / 2) - (w / 2 - r)
    dy = np.abs(yy - h / 2) - (h / 2 - r)
    qx, qy = np.maximum(dx, 0), np.maximum(dy, 0)
    return (qx ** 4 + qy ** 4) ** 0.25 - r + np.minimum(np.maximum(dx, dy), 0)


def sq_arr(d, layers):
    """Filled squircles (superellipse, n=4), outer layer first."""
    yy, xx = np.mgrid[0:d, 0:d]
    x, y = np.abs(xx - (d - 1) / 2), np.abs(yy - (d - 1) / 2)
    r4 = (x ** 4 + y ** 4) ** 0.25
    rgb, alpha = np.zeros((d, d, 3)), np.zeros((d, d))
    for rad, col in layers:
        cov = np.clip(rad - r4 + 0.5, 0, 1)
        rgb = rgb * (1 - cov[..., None]) + np.array(col) * cov[..., None]
        alpha = np.maximum(alpha, cov)
    return np.dstack([rgb, alpha * 255]).astype(np.uint8)


def disc_arr(d, layers):
    """Filled circles, outer layer first."""
    yy, xx = np.mgrid[0:d, 0:d]
    r = np.hypot(xx - (d - 1) / 2, yy - (d - 1) / 2)
    rgb, alpha = np.zeros((d, d, 3)), np.zeros((d, d))
    for rad, col in layers:
        cov = np.clip(rad - r + 0.5, 0, 1)
        rgb = rgb * (1 - cov[..., None]) + np.array(col) * cov[..., None]
        alpha = np.maximum(alpha, cov)
    return np.dstack([rgb, alpha * 255]).astype(np.uint8)


# ---------- easter egg: the logo bear, drawn frame by frame (needs Pillow) ----------
EGG_SECS, EGG_FRAMES = 2.6, 78


def ease(u):
    u = min(1.0, max(0.0, u))
    return u * u * (3 - 2 * u)


def rounded_poly(pts, r, steps=10):
    """Convex polygon with corners rounded to radius r."""
    out, n = [], len(pts)
    for i in range(n):
        p0, p1, p2 = pts[i - 1], pts[i], pts[(i + 1) % n]
        a = (p0[0] - p1[0], p0[1] - p1[1]); b = (p2[0] - p1[0], p2[1] - p1[1])
        la, lb = math.hypot(*a), math.hypot(*b)
        a, b = (a[0] / la, a[1] / la), (b[0] / lb, b[1] / lb)
        ang = math.acos(max(-1.0, min(1.0, a[0] * b[0] + a[1] * b[1])))
        t, h = r / math.tan(ang / 2), r / math.sin(ang / 2)
        bis = (a[0] + b[0], a[1] + b[1]); lb2 = math.hypot(*bis)
        c = (p1[0] + bis[0] / lb2 * h, p1[1] + bis[1] / lb2 * h)
        s0 = math.atan2(p1[1] + a[1] * t - c[1], p1[0] + a[0] * t - c[0])
        s1 = math.atan2(p1[1] + b[1] * t - c[1], p1[0] + b[0] * t - c[0])
        da = (s1 - s0 + math.pi) % (2 * math.pi) - math.pi
        out += [(c[0] + r * math.cos(s0 + da * k / steps), c[1] + r * math.sin(s0 + da * k / steps)) for k in range(steps + 1)]
    return out


def bear_frame(size, t):
    """The logo at time t of the easter egg (t=0 and t=EGG_SECS are the plain logo). Coordinates are on a 1024 grid."""
    from PIL import Image, ImageDraw
    eyes = ease(t / 0.35) * (1 - ease((t - 2.2) / 0.4))
    wink = 1 - math.sin(math.pi * min(1.0, max(0.0, (t - 1.2) / 0.3)))
    up = ease((t - 0.15) / 0.6) * (1 - ease((t - 1.9) / 0.55))
    K = 4 * size / 1024
    W = 4 * size
    img = Image.new('RGBA', (W, W), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    q = lambda *v: [x * K for x in v]
    bear, cup, hil, white = (21, 23, 28), (40, 44, 56), (82, 90, 109), (255, 255, 255)
    for cx, cy in ((252, 292), (772, 292)):
        d.ellipse(q(cx - 108, cy - 108, cx + 108, cy + 108), fill=bear)
    d.ellipse(q(184, 244, 840, 892), fill=bear)
    d.arc(q(170, 230, 854, 914), 212, 328, fill=cup, width=int(58 * K))
    d.arc(q(170, 230, 854, 914), 214, 326, fill=hil, width=max(1, int(10 * K)))
    for side in (-1, 1):
        base = [(88, 444), (250, 404), (250, 752), (88, 712)]
        cx0, cy0, cx1, cy1, ang = 169, 578, 232, 270, -math.radians(44) * up   # onto the ear, lying along the head
        cx, cy = cx0 + (cx1 - cx0) * up, cy0 + (cy1 - cy0) * up
        pts = []
        for x, y in base:
            x, y = x - cx0, y - cy0
            x, y = x * math.cos(ang) + y * math.sin(ang), -x * math.sin(ang) + y * math.cos(ang)
            pts.append((cx + x, cy + y))
        if side > 0:
            pts = [(1024 - x, y) for x, y in pts][::-1]
        d.polygon([(x * K, y * K) for x, y in rounded_poly(pts, 50)], fill=cup)
    d.ellipse(q(372, 584, 652, 796), fill=(246, 240, 230))
    d.ellipse(q(460, 602, 564, 670), fill=bear)
    d.line(q(512, 668, 512, 708), fill=bear, width=int(12 * K))
    d.arc(q(468, 686, 512, 730), 20, 160, fill=bear, width=int(12 * K))
    d.arc(q(512, 686, 556, 730), 20, 160, fill=bear, width=int(12 * K))
    for x, o in ((396, eyes), (628, eyes * wink)):
        if eyes > 0.02:
            ry = max(4, 30 * o)
            d.ellipse(q(x - 30, 566 - ry, x + 30, 566 + ry), fill=white)
    m = np.array(img)[..., 3] > 0
    for k in range(int(round(24 * K))):                   # one white outline around the whole figure
        g = m.copy()
        g[1:] |= m[:-1]; g[:-1] |= m[1:]; g[:, 1:] |= m[:, :-1]; g[:, :-1] |= m[:, 1:]
        if k % 2:
            g[1:, 1:] |= m[:-1, :-1]; g[:-1, :-1] |= m[1:, 1:]; g[1:, :-1] |= m[:-1, 1:]; g[:-1, 1:] |= m[1:, :-1]
        m = g
    out = Image.new('RGBA', (W, W), (0, 0, 0, 0))
    ImageDraw.Draw(out).ellipse((0, 0, W - 1, W - 1), fill=(255, 117, 24))
    out.paste(Image.new('RGBA', (W, W), white + (255,)), (0, 0), Image.fromarray((m * 255).astype(np.uint8)))
    out.alpha_composite(img)
    return out.resize((size, size), Image.LANCZOS)


def png_b64_pil(im):
    b = io.BytesIO()
    im.save(b, 'PNG')
    return base64.b64encode(b.getvalue()).decode()


def squash_arr(d, layers, p0, t):
    """A knob being squashed: the round (p0=2) or squircle (p0=4) knob of size d turns, as t goes 0..1, into a wide and
    flat rhombus, like a ball pressed under a finger. Edges are anti-aliased by 4x4 supersampling."""
    sx, sy, p = 1 + 0.42 * t, 1 - 0.12 * t, p0 + (1.5 - p0) * t
    w, h, ss = int(math.ceil(d * sx)) | 1, d, 4
    yy, xx = np.mgrid[0:h * ss, 0:w * ss]
    x = np.abs((xx + 0.5) / ss - w / 2)
    y = np.abs((yy + 0.5) / ss - h / 2)
    rgb, alpha = np.zeros((h * ss, w * ss, 3)), np.zeros((h * ss, w * ss))
    for rad, col in layers:
        a, b = rad * sx, rad * sy
        inside = ((x / a) ** p + (y / b) ** p) <= 1.0
        rgb[inside] = col
        alpha = np.maximum(alpha, inside)
    rgb = rgb.reshape(h, ss, w, ss, 3).mean(axis=(1, 3))
    alpha = alpha.reshape(h, ss, w, ss).mean(axis=(1, 3))
    rgb = rgb / np.maximum(alpha, 1e-6)[..., None]          # un-premultiply the edge pixels
    return np.dstack([np.clip(rgb, 0, 255), alpha * 255]).astype(np.uint8)


def ripple_arr(w, h, grow, bt, col, alpha, r):
    """Outline of the control, `grow` px larger on every side, with the given opacity."""
    sdf = squircle_sdf(w + 2 * grow, h + 2 * grow, r + grow)
    ring = np.clip(0.5 - sdf, 0, 1) - np.clip(0.5 - (sdf + bt), 0, 1)
    a = np.zeros(ring.shape + (4,), np.uint8)
    a[..., :3] = col
    a[..., 3] = (ring * alpha * 255).astype(np.uint8)
    return a


def frame_arr(w, h, r, bt, line, top, body, header_h):
    """Squircle panel with an outline; the first `header_h` rows use a different fill."""
    sdf = squircle_sdf(w, h, r)
    ring = np.clip(0.5 - sdf, 0, 1) - np.clip(0.5 - (sdf + bt), 0, 1)
    inner = np.clip(0.5 - (sdf + bt), 0, 1)
    fill = np.where((np.arange(h) < header_h)[:, None, None], np.array(top, float), np.array(body, float))
    a = ring + (1 - ring) * inner
    rgb = (ring[..., None] * np.array(line, float) + ((1 - ring) * inner)[..., None] * fill) / np.maximum(a, 1e-6)[..., None]
    return np.dstack([rgb, a * 255]).astype(np.uint8)


def chip_arr(w, h, r, bt, sel, color, rainbow, pal):
    """Squircle button. `color` gives a solid coloured border; `rainbow` a spectrum gradient."""
    sdf = squircle_sdf(w, h, r)
    ring = np.clip(0.5 - sdf, 0, 1) - np.clip(0.5 - (sdf + bt), 0, 1)
    inner = np.clip(0.5 - (sdf + bt), 0, 1)
    if rainbow:
        cols = np.array([hexrgb(c) for c in COLORS], float)
        xs = np.linspace(0.05, 0.95, 10)
        xn = (np.arange(w) + 0.5) / w
        row = np.stack([np.interp(xn, xs, cols[:, k]) for k in range(3)], 1)
        col = np.broadcast_to(row[None], (h, w, 3))
        tint = np.array(hexrgb(COLORS[6]), float)
    elif color is not None:
        col = np.broadcast_to(np.array(color, float), (h, w, 3))
        tint = np.array(color, float)
    else:
        base = np.array(pal['acc'] if sel else pal['line'], float)
        col = np.broadcast_to(base, (h, w, 3))
        tint = np.array(pal['acc'], float)
    if sel:
        col = col + (255 - col) * 0.2
    fill, fa = (tint, 0.22) if sel else (np.array(pal['chip'], float), 0.85)
    a = ring + (1 - ring) * inner * fa
    rgb = (ring[..., None] * col + ((1 - ring) * inner * fa)[..., None] * fill) / np.maximum(a, 1e-6)[..., None]
    return np.dstack([rgb, a * 255]).astype(np.uint8)


def icon_arr(kind, d, col):
    """Vector icons rasterised with 4x supersampling; unit square coordinates."""
    k = 4
    n = d * k
    Y, X = (np.mgrid[0:n, 0:n] + 0.5) / n
    m = np.zeros((n, n), bool)

    def cap(ax, ay, bx, by, w):
        vx, vy = bx - ax, by - ay
        t = np.clip(((X - ax) * vx + (Y - ay) * vy) / (vx * vx + vy * vy + 1e-12), 0, 1)
        np.logical_or(m, np.hypot(X - ax - t * vx, Y - ay - t * vy) <= w / 2, out=m)

    def disc(cx, cy, r):
        np.logical_or(m, np.hypot(X - cx, Y - cy) <= r, out=m)

    def ring(cx, cy, r, w, a0=0.0, a1=360.0):
        mm = np.abs(np.hypot(X - cx, Y - cy) - r) <= w / 2
        if a1 - a0 < 360:
            ang = np.degrees(np.arctan2(Y - cy, X - cx)) % 360
            mm &= (ang >= a0) & (ang <= a1)
        np.logical_or(m, mm, out=m)

    def tri(p, q, s):
        def side(a, b):
            return (X - b[0]) * (a[1] - b[1]) - (a[0] - b[0]) * (Y - b[1])
        d1, d2, d3 = side(p, q), side(q, s), side(s, p)
        np.logical_or(m, ~(((d1 < 0) | (d2 < 0) | (d3 < 0)) & ((d1 > 0) | (d2 > 0) | (d3 > 0))), out=m)

    if kind == 'play':
        tri((.33, .2), (.33, .8), (.8, .5))
    elif kind == 'stop':
        np.logical_or(m, (np.abs(X - .5) <= .2) & (np.abs(Y - .5) <= .2), out=m)
    elif kind == 'pause':
        cap(.36, .22, .36, .78, .17)
        cap(.64, .22, .64, .78, .17)
    elif kind == 'reset':
        ring(.5, .52, .27, .1, 25, 305)
        a = math.radians(25)
        px_, py_ = .5 + .27 * math.cos(a), .52 + .27 * math.sin(a)
        dx, dy = math.sin(a), -math.cos(a)
        tri((px_ + .13 * math.cos(a), py_ + .13 * math.sin(a)), (px_ - .13 * math.cos(a), py_ - .13 * math.sin(a)),
            (px_ + .2 * dx, py_ + .2 * dy))
    elif kind in ('down', 'up'):
        y0, y1 = (.38, .64) if kind == 'down' else (.64, .38)
        cap(.26, y0, .5, y1, .11)
        cap(.5, y1, .74, y0, .11)
    elif kind == 'wave':
        pts = [(.13 + .74 * i / 28, .5 + .2 * math.sin(2 * math.pi * 1.5 * i / 28)) for i in range(29)]
        for p, q in zip(pts, pts[1:]):
            cap(p[0], p[1], q[0], q[1], .1)
    elif kind == 'tune':
        for y in (.3, .5, .7):
            cap(.18, y, .82, y, .07)
        disc(.35, .3, .1); disc(.65, .5, .1); disc(.46, .7, .1)
    elif kind == 'mini':
        for a, b in (((.2, .28), (.8, .28)), ((.8, .28), (.8, .72)), ((.8, .72), (.2, .72)), ((.2, .72), (.2, .28))):
            cap(a[0], a[1], b[0], b[1], .075)
        np.logical_or(m, (X > .46) & (X < .72) & (Y > .46) & (Y < .64), out=m)
    elif kind == 'gear':
        ring(.5, .5, .2, .13)
        for i in range(8):
            a = math.radians(45 * i)
            cap(.5 + .26 * math.cos(a), .5 + .26 * math.sin(a), .5 + .37 * math.cos(a), .5 + .37 * math.sin(a), .13)
    elif kind == 'power':
        ring(.5, .57, .27, .1, 0, 232)
        ring(.5, .57, .27, .1, 308, 360)
        cap(.5, .16, .5, .5, .1)
    elif kind == 'back':
        cap(.62, .24, .38, .5, .11)
        cap(.38, .5, .62, .76, .11)
    elif kind == 'chev_r':
        cap(.38, .26, .62, .5, .11)
        cap(.62, .5, .38, .74, .11)
    elif kind == 'chev_d':
        cap(.26, .38, .5, .62, .11)
        cap(.5, .62, .74, .38, .11)
    elif kind == 'check':
        cap(.22, .52, .42, .72, .14)
        cap(.42, .72, .8, .3, .14)
    cov = m.reshape(d, k, d, k).mean((1, 3))
    a = np.zeros((d, d, 4), np.uint8)
    a[..., :3] = col
    a[..., 3] = (cov * 255).astype(np.uint8)
    return a


class GUID(ctypes.Structure):
    _fields_ = [('a', ctypes.c_ulong), ('b', ctypes.c_ushort), ('c', ctypes.c_ushort), ('d', ctypes.c_ubyte * 8)]


def com_guid(text):
    g = GUID()
    ctypes.windll.ole32.CLSIDFromString(text, ctypes.byref(g))
    return g


def com_method(ptr, idx, *argtypes):
    """Bind vtable entry `idx` of the COM object `ptr`; the returned function takes the object first."""
    vt = ctypes.cast(ctypes.cast(ptr, ctypes.POINTER(ctypes.c_void_p))[0], ctypes.POINTER(ctypes.c_void_p))
    return ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p, *argtypes)(vt[idx])


def com_release(ptr):
    if ptr and ptr.value:
        com_method(ptr, 2)(ptr)


def default_render_device():
    """Open Windows' default playback endpoint (IMMDevice); returns a c_void_p to release, or None."""
    ole32 = ctypes.windll.ole32
    enum, dev = ctypes.c_void_p(), ctypes.c_void_p()
    if ole32.CoCreateInstance(ctypes.byref(com_guid('{BCDE0395-E52F-467C-8E3D-C4579291692E}')), None, 23,
                              ctypes.byref(com_guid('{A95664D2-9614-4F35-A746-DE8DB63617E6}')), ctypes.byref(enum)) != 0:
        return None
    try:
        if com_method(enum, 4, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_void_p))(enum, 0, 0, ctypes.byref(dev)) != 0:
            return None
        return dev
    finally:
        com_release(enum)


def default_render_id():
    """ID of Windows' default playback device (Core Audio through ctypes); None when unavailable."""
    dev = default_render_device()
    if not dev:
        return None
    try:
        out = ctypes.c_void_p()
        if com_method(dev, 5, ctypes.POINTER(ctypes.c_void_p))(dev, ctypes.byref(out)) != 0:
            return None
        did = ctypes.wstring_at(out.value)
        ctypes.windll.ole32.CoTaskMemFree(ctypes.c_void_p(out.value))
        return did
    finally:
        com_release(dev)


# Only these programs lower the noise: browsers (videos) and media players. Games, chat and everything else do not.
DUCK_APPS = {'chrome.exe', 'msedge.exe', 'firefox.exe', 'brave.exe', 'opera.exe', 'vivaldi.exe', 'librewolf.exe',
             'waterfox.exe', 'floorp.exe', 'zen.exe', 'arc.exe', 'chromium.exe', 'iexplore.exe',
             'vlc.exe', 'mpv.exe', 'mpc-hc.exe', 'mpc-hc64.exe', 'mpc-be.exe', 'mpc-be64.exe', 'potplayer.exe',
             'potplayermini.exe', 'potplayermini64.exe', 'wmplayer.exe', 'microsoft.media.player.exe', 'video.ui.exe',
             'spotify.exe', 'applemusic.exe', 'itunes.exe', 'foobar2000.exe', 'aimp.exe', 'musicbee.exe', 'winamp.exe',
             'tidal.exe', 'deezer.exe', 'plex.exe', 'kodi.exe', 'stremio.exe'}


def process_name(pid):
    """Lower-case executable name of a process, or '' when it cannot be read."""
    try:
        k = ctypes.windll.kernel32
        k.OpenProcess.restype = ctypes.c_void_p
        h = k.OpenProcess(0x1000, False, pid)                       # PROCESS_QUERY_LIMITED_INFORMATION
        if not h:
            return ''
        try:
            buf, size = ctypes.create_unicode_buffer(1024), ctypes.c_ulong(1024)
            if k.QueryFullProcessImageNameW(ctypes.c_void_p(h), 0, buf, ctypes.byref(size)):
                return os.path.basename(buf.value).lower()
        finally:
            k.CloseHandle(ctypes.c_void_p(h))
    except Exception:
        pass
    return ''


def other_audio_peak(own_pid):
    """Highest output peak (0..1) among the active audio sessions of browsers and media players on the default device."""
    P = ctypes.POINTER(ctypes.c_void_p)
    dev = default_render_device()
    if not dev:
        return 0.0
    peak, mgr, lst = 0.0, ctypes.c_void_p(), ctypes.c_void_p()
    try:
        iid = com_guid('{77AA99A0-1BD6-484F-8BC7-2C654C9A9B6F}')      # IAudioSessionManager2
        if com_method(dev, 3, ctypes.POINTER(GUID), ctypes.c_ulong, ctypes.c_void_p, P)(dev, ctypes.byref(iid), 23, None, ctypes.byref(mgr)) != 0:
            return 0.0
        if com_method(mgr, 5, P)(mgr, ctypes.byref(lst)) != 0:         # GetSessionEnumerator
            return 0.0
        count = ctypes.c_int()
        if com_method(lst, 3, ctypes.POINTER(ctypes.c_int))(lst, ctypes.byref(count)) != 0:
            return 0.0
        iid2 = com_guid('{BFB7FF88-7239-4FC9-8FA2-07C950BE9C6D}')     # IAudioSessionControl2
        iidm = com_guid('{C02216F6-8C67-4B5B-9D00-D008E73E0064}')     # IAudioMeterInformation
        for i in range(count.value):
            ctl, c2, meter = ctypes.c_void_p(), ctypes.c_void_p(), ctypes.c_void_p()
            if com_method(lst, 4, ctypes.c_int, P)(lst, i, ctypes.byref(ctl)) != 0:
                continue
            try:
                state = ctypes.c_int()
                if com_method(ctl, 3, ctypes.POINTER(ctypes.c_int))(ctl, ctypes.byref(state)) != 0 or state.value != 1:
                    continue                                           # only active sessions
                if com_method(ctl, 0, ctypes.POINTER(GUID), P)(ctl, ctypes.byref(iid2), ctypes.byref(c2)) != 0:
                    continue
                try:
                    pid = ctypes.c_ulong()
                    if com_method(c2, 14, ctypes.POINTER(ctypes.c_ulong))(c2, ctypes.byref(pid)) != 0 or pid.value in (0, own_pid):
                        continue                                       # system sounds and EarBear itself do not count
                    if process_name(pid.value) not in DUCK_APPS:
                        continue                                       # games and other programs do not count
                finally:
                    com_release(c2)
                if com_method(ctl, 0, ctypes.POINTER(GUID), P)(ctl, ctypes.byref(iidm), ctypes.byref(meter)) == 0:
                    try:
                        val = ctypes.c_float()
                        if com_method(meter, 3, ctypes.POINTER(ctypes.c_float))(meter, ctypes.byref(val)) == 0:
                            peak = max(peak, val.value)
                    finally:
                        com_release(meter)
            finally:
                com_release(ctl)
        return peak
    finally:
        com_release(lst)
        com_release(mgr)
        com_release(dev)


LCD_SEGS = {'0': 'abcdef', '1': 'bc', '2': 'abged', '3': 'abgcd', '4': 'fgbc', '5': 'afgcd', '6': 'afgedc',
            '7': 'abc', '8': 'abcdefg', '9': 'abcdfg'}


def lcd_glyph(ch, h, lit, ghost):
    """One seven-segment digit (or colon), slanted, with its unlit segments faintly visible. RGBA array, height h."""
    k, t, slant = 4, 0.085, 0.14
    s = h / 2.0                                         # pixels per unit; a digit is 1 x 2 units
    colon = ch == ':'
    w = max(2, int(round((0.42 if colon else 1.0 + slant) * s)))
    Y, X = (np.mgrid[0:h * k, 0:w * k] + 0.5) / (s * k)

    def cover(mask):
        return mask.reshape(h, k, w, k).mean((1, 3))
    if colon:
        segs = {n: (np.abs(X - 0.21) <= 0.085) & (np.abs(Y - cy) <= 0.085) for n, cy in (('p', 0.62), ('q', 1.38))}
        on = 'pq'
    else:
        U = X - slant * (1 - Y / 2)

        def hs(cy):
            d = np.abs(Y - cy)
            return (d <= t) & (np.abs(U - 0.5) <= 0.48 - d)

        def vs(cx, cy):
            d = np.abs(U - cx)
            return (d <= t) & (np.abs(Y - cy) <= (1 - t) / 2 - 0.12 - d)
        segs = dict(a=hs(t), g=hs(1.0), d=hs(2 - t), f=vs(t, (1 + t) / 2), b=vs(1 - t, (1 + t) / 2),
                    e=vs(t, (3 - t) / 2), c=vs(1 - t, (3 - t) / 2))
        on = LCD_SEGS.get(ch, '')
    gc = cover(np.logical_or.reduce(list(segs.values())))
    lc = cover(np.logical_or.reduce([segs[c] for c in on])) if on else np.zeros_like(gc)
    rgb = (np.array(lit, float) * lc[..., None] + np.array(ghost, float) * (gc - lc)[..., None]) / np.maximum(gc, 1e-6)[..., None]
    return np.dstack([rgb, gc * 255]).astype(np.uint8)


def lcd_arr(text, h, lit, ghost):
    """A row of seven-segment glyphs."""
    gap = np.zeros((h, max(2, int(round(0.3 * h / 2))), 4), np.uint8)
    parts = []
    for ch in text:
        parts += [lcd_glyph(ch, h, lit, ghost), gap]
    return np.concatenate(parts[:-1], axis=1)


def parse_minutes(text):
    """Typed duration -> minutes. Accepts 1:30, 1:30:00, 90, 90m, 2h, 1h30, 1h 30m; None if not understood."""
    t = text.strip().lower().replace(',', '.')
    if not t:
        return None
    m = re.fullmatch(r'(\d+):(\d{1,2})(?::(\d{1,2}))?', t)
    if m:
        h, mi, se = int(m.group(1)), int(m.group(2)), int(m.group(3) or 0)
        return h * 60 + mi + (1 if se >= 30 else 0)
    m = re.fullmatch(r'(?:(\d+(?:\.\d+)?)\s*h)?\s*(?:(\d+(?:\.\d+)?)\s*(?:m|min)?)?', t)
    if m and (m.group(1) or m.group(2)):
        return int(round(float(m.group(1) or 0) * 60 + float(m.group(2) or 0)))
    return None


def fmt_clock(secs):
    secs = int(max(0, secs))
    return '%02d:%02d:%02d' % (secs // 3600, secs % 3600 // 60, secs % 60)


